diff --git a/lib/parsedate.c b/lib/parsedate.c
index b4dd97b..9e2c45f 100644
--- a/lib/parsedate.c
+++ b/lib/parsedate.c
@@ -141,7 +141,6 @@ static const struct tzinfo tzone[] = {
   { "W", 10 * 60 },            /* Whiskey */
   { "X", 11 * 60 },            /* X-ray */
   { "Y", 12 * 60 },            /* Yankee */
-  { "Z",       0 },            /* Zulu, zero meridian, a.k.a. UTC */
 };

 /* two-letter time zones */
@@ -337,6 +336,10 @@ UNITTEST int checktz(const char *check, size_t len)
     /* short-cut single letter names */
     if((check[0] < 'A') || (check[0] > 'Z') || (check[0] == 'J'))
       return -1; /* no such tz */
+    if(check[0] == 'Z')
+      /* Zulu, zero meridian, a.k.a. UTC: the most common single-letter
+         zone, skip the table lookup for it */
+      return 0;
     return tzone[check[0] - 'A'].offset * 60;
   }
   else if(len == 2) {

